package glitch

import data.glitch_lib

sensitive_credential_patterns := {
    "password", "passwd", "pwd", "secret", "secret_key", "credentials", "auth_token",
    "api_key", "access_key", "private_key", "user_pass", "db_password", "admin_password",
    "service_account_key", "connection_string", "datasource", "sha512_password", "sha256_password"
}

weak_password_values := {
    "password", "admin", "root", "123456", "default", "changeme",
    "12345", "12345678", "qwerty", "letmein", "welcome", "monkey",
    "1234567890", "pass", "password123", "admin123", "root123", "telarista", "passw0rd"
}

secure_prefix_patterns := {"arn:", "${", "{{", "ref(", "var.", "module.", "data.", "vault(", "secret(", "lookup(", "key:"}

excluded_context_patterns := {"user", "account", "admin_user", "admin_user", "directory", "log_directory", "admin", "privilege", "role", "no_password"}

is_credential_attribute(name) {
    lower_name := lower(name)
    pattern := sensitive_credential_patterns[_]
    contains(lower_name, pattern)
}

is_password_key(name) {
    regex.match("(?i).*(?:password|passwd|secret|sha512_password|sha256_password).*", name)
}

contains(str, substr) {
    regex.match(sprintf("(?i).*%s.*", [substr]), str)
}

is_weak_hardcoded_password(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    weak_password_values[_] == lower_val
}

is_external_reference(str) {
    prefix := secure_prefix_patterns[_]
    startswith(str, prefix)
}

is_safe_context(name) {
    lower_name := lower(name)
    excluded_context_patterns[_] == lower_name
}

traverse_value_for_password(val, parent_key) {
    val.ir_type == "String"
    is_password_key(parent_key)
    count(val.value) > 0
    not is_external_reference(val.value)
}

traverse_value_for_password(val, parent_key) {
    val.ir_type == "String"
    is_weak_hardcoded_password(val)
}

traverse_hash_for_credentials(hash) {
    hash.ir_type == "Hash"
    entry := hash.value[_]
    key_str := entry[0]
    val := entry[1]
    key_str.ir_type == "String"
    key_name := key_str.value
    is_password_key(key_name)
    traverse_value_for_password(val, key_name)
}

