password_patterns := {"password", "passwd", "pwd", "secret", "credentials", "auth_token", "api_key", "access_key", "private_key", "secret_key", "user_pass", "db_password", "admin_password", "service_account_key", "connection_string", "initial_password", "bootstrap_password", "setup_credential", "master_password", "replication_password", "root_password", "vpn_psk", "ipsec_secret", "certificate_password", "image_pull_secret", "registry_password", "sha512_password"}

weak_passwords := {"password", "123456", "123456789", "qwerty", "password123", "admin", "letmein", "welcome", "monkey", "12345678", "abc123", "football", "iloveyou", "admin123", "welcome123", "password1", "123123", "987654321", "qwertyuiop", "password123!", "changeme", "default", "root", "root123", "passw0rd", "telarista", "some_password", "test", "temp", "temporary"}

secure_external_indicators := {"secret_ref", "vault_path", "arn", "external_id", "data_source", "kms_key_id", "vault_key", "sealed_secret"}

is_password_key(key) {
    lower_key := lower(key)
    pattern := password_patterns[_]
    contains(lower_key, pattern)
}

is_weak_password(str) {
    lower_str := lower(str)
    weak := weak_passwords[_]
    lower_str == weak
}

has_var_reference(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
} else {
    walk(node, [_, n])
    n.ir_type == "FunctionCall"
    contains(n.name, "${")
} else {
    walk(node, [_, n])
    n.ir_type == "MethodCall"
}

is_external_reference(str) {
    indicator := secure_external_indicators[_]
    contains(str, indicator)
} else {
    contains(str, "${")
} else {
    contains(str, "{{")
} else {
    contains(str, "lookup(")
} else {
    contains(str, "vault(")
} else {
    contains(str, "ref(")
} else {
    regex.match("^\\s*var\\.", str)
} else {
    regex.match("^\\s*module\\.", str)
} else {
    regex.match("^\\s*data\\.", str)
}

is_safe_value(val) {
    val.ir_type == "String"
    is_external_reference(val.value)
} else {
    has_var_reference(val)
}

is_hardcoded_string(val) {
    val.ir_type == "String"
    not is_safe_value(val)
    count(val.value) > 0
}

find_hash_entries_with_password_keys(hash, parent_key) = entries {
    entries := {[key_str, val] |
        entry := hash.value[_]
        key_expr := entry[0]
        val := entry[1]
        key_expr.ir_type == "String"
        key_str := key_expr.value

        combined_key := sprintf("%s.%s", [parent_key, key_str])
        is_password_key(combined_key)
    }
} else = entries {
    entries := {[key_str, val] |
        entry := hash.value[_]
        key_expr := entry[0]
        val := entry[1]
        key_expr.ir_type == "String"
        key_str := key_expr.value

        is_password_key(key_str)
    }
}

check_hash_for_passwords(hash, parent_key) {
    entries := find_hash_entries_with_password_keys(hash, parent_key)
    count(entries) > 0
    [_, val] := entries[_]
    is_hardcoded_string(val)
} else {
    entries := find_hash_entries_with_password_keys(hash, parent_key)
    count(entries) > 0
    [_, val] := entries[_]
    val.ir_type == "String"
    is_weak_password(val.value)
}

nested_hash_has_password_string(hash, parent_key) {
    entry := hash.value[_]
    key_expr := entry[0]
    val := entry[1]
    key_expr.ir_type == "String"
    key_str := key_expr.value

    new_key := sprintf("%s.%s", [parent_key, key_str])
    is_password_key(new_key)
    is_hardcoded_string(val)
} else {
    entry := hash.value[_]
    key_expr := entry[0]
    val := entry[1]
    key_expr.ir_type == "String"
    key_str := key_expr.value

    new_key := sprintf("%s.%s", [parent_key, key_str])
    is_password_key(new_key)
    val.ir_type == "String"
    is_weak_password(val.value)
} else {
    entry := hash.value[_]
    val := entry[1]
    val.ir_type == "Hash"
    nested_hash_has_password_string(val, parent_key)
} else {
    entry := hash.value[_]
    key_expr := entry[0]
    val := entry[1]
    key_expr.ir_type == "String"
    key_str := key_expr.value

    is_password_key(key_str)
    is_hardcoded_string(val)
} else {
    entry := hash.value[_]
    key_expr := entry[0]
    val := entry[1]
    key_expr.ir_type == "String"
    key_str := key_expr.value

    is_password_key(key_str)
    val.ir_type == "String"
    is_weak_password(val.value)
} else {
    entry := hash.value[_]
    val := entry[1]
    val.ir_type == "Hash"
    key_expr := entry[0]
    key_expr.ir_type == "String"
    nested_hash_has_password_string(val, key_expr.value)
}

array_elem_has_hardcoded_password(arr, parent_key) {
    elem := arr.value[_]
    elem.ir_type == "String"
    is_weak_password(elem.value)
    not is_safe_value(elem)
}

array_has_hardcoded_password(arr, parent_key) {
    is_password_key(parent_key)
    array_elem_has_hardcoded_password(arr, parent_key)
}

find_containing_key_for_value(parent, target_val) = key {
    walk(parent, [_, node])
    node.ir_type == "Attribute"
    node.value == target_val
    key := node.name
} else = key {
    walk(parent, [_, node])
    node.ir_type == "Variable"
    node.value == target_val
    key := node.name
} else = key {
    walk(parent, [_, hash])
    hash.ir_type == "Hash"
    entry := hash.value[_]
    entry[1] == target_val
    key_expr := entry[0]
    key_expr.ir_type == "String"
    key := key_expr.value
} else = "unknown" {
    true
}

