password_patterns := {"password", "passwd", "pwd", "secret", "credentials", "auth_token", "api_key", "access_key", "private_key", "secret_key", "user_pass", "db_password", "admin_password", "service_account_key", "connection_string", "initial_password", "bootstrap_password", "setup_credential", "master_password", "replication_password", "root_password", "vpn_psk", "ipsec_secret", "certificate_password", "image_pull_secret", "registry_password"}

