is_safe_value(val) {
    val.ir_type == "String"
    contains(val.value, "${")
} else {
    val.ir_type == "String"
    contains(val.value, "{{")
} else {
    val.ir_type == "String"
    contains(val.value, "lookup(")
} else {
    val.ir_type == "String"
    contains(val.value, "vault(")
} else {
    val.ir_type == "String"
    contains(val.value, "var.")
} else {
    has_var_reference(val)
} else {
    has_function_call(val)
} else {
