is_hardcoded_string(val) {
    val.ir_type == "String"
    not is_safe_value(val)
    count(val.value) > 0
}

is_password_entry(entry, parent_key) {
    entry[0].ir_type == "String"
    key_str := entry[0].value
    full_key := sprintf("%s.%s", [parent_key, key_str])
    is_password_key(full_key)
}

is_direct_password_entry(entry) {
    entry[0].ir_type == "String"
    key_str := entry[0].value
    is_password_key(key_str)
}

check_hash_entries_for_password(hash, parent_key) {
    entry := hash.value[_]
    is_password_entry(entry, parent_key)
    is_hardcoded_string(entry[1])
} else {
    entry := hash.value[_]
    is_password_entry(entry, parent_key)
    entry[1].ir_type == "String"
    is_weak_password(entry[1].value)
} else {
    entry := hash.value[_]
    is_direct_password_entry(entry)
    is_hardcoded_string(entry[1])
} else {
    entry := hash.value[_]
    is_direct_password_entry(entry)
    entry[1].ir_type == "String"
    is_weak_password(entry[1].value)
}

check_nested_hash_for_password(hash, parent_key) {
    check_hash_entries_for_password(hash, parent_key)
} else {
    entry := hash.value[_]
    entry[1].ir_type == "Hash"
    check_nested_hash_for_password(entry[1], parent_key)
} else {
    entry := hash.value[_]
    entry[0].ir_type == "String"
    key_str := entry[0].value
    is_password_key(key_str)
    entry[1].ir_type == "Hash"
    check_nested_hash_for_password(entry[1], key_str)
}

